// Reads synthetic fixture HTML generated by test_master_ride_pricing.php --render-fixture.
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const fs=require('fs');
const check=(ok,message)=>{if(!ok)throw Error(message);};
(async()=>{
 const browser=await chromium.launch({headless:true,...(process.env.CHROMIUM_EXECUTABLE_PATH?{executablePath:process.env.CHROMIUM_EXECUTABLE_PATH}:{})});
 try{
  const page=await browser.newPage();let post='';
  const html=fs.readFileSync('/tmp/master-ride-scheme-fixture.html','utf8');
  await page.route('http://pricing.test/**',route=>{if(route.request().method()==='POST')post=route.request().postData();return route.fulfill({contentType:'text/html; charset=utf-8',body:html});});
  await page.goto('http://pricing.test/pricing_scheme_edit.php?id=22');
  check(await page.locator('input[name="master_class_ids[]"]').count()===3,'Catalogue classes missing');
  check(await page.locator('input[name="master_class_ids[]"]:checked').count()===1,'Saved selection not retained');
  check(await page.locator('input[name^="row_price"]').count()===0,'Scheme exposes independent price inputs');
  check(await page.locator('input[name="csrf"]').inputValue()!=='','Missing CSRF protection');
  check(await page.evaluate(()=>!window.masterInjected),'Master class name was executed as HTML');
  check((await page.locator('tbody').textContent()).includes('<script>window.masterInjected=1</script>'),'Class name escaped incorrectly');
  const boxes=page.locator('input[name="master_class_ids[]"]');await boxes.nth(0).check();await boxes.nth(1).uncheck();
  await Promise.all([page.waitForNavigation(),page.getByRole('button',{name:'Save Scheme',exact:true}).click()]);
  const fields=new URLSearchParams(post);
  check(fields.getAll('master_class_ids[]').length===1,'Enabled classes submitted incorrectly');
  check(!Array.from(fields.keys()).some(key=>key.startsWith('row_price')),'Unexpected independent prices in submitted scheme');
  await page.setContent(fs.readFileSync('/tmp/master-ride-event-draft.html','utf8'));
  check(await page.locator('#pricingRowsTbody input[name^="event_row_price"]').first().evaluate(el=>el.readOnly),'Draft ride rate can be edited independently');
  check(!(await page.locator('#pricingRowsTbody input[type=checkbox][name^="event_row_enabled"]').first().isDisabled()),'Draft class enabling incorrectly locked');
  check(await page.locator('#addPricingRowBtn').isHidden(),'Draft ride allows arbitrary new price rows');
  check(await page.locator('#pricingRowsTbody select[name^="event_row_rider_eligibility"]').first().isDisabled(),'Master rider eligibility editable in event');
  await page.setContent(fs.readFileSync('/tmp/master-ride-event-locked.html','utf8'));
  check(await page.locator('#applyPricingSchemeBtn').isDisabled(),'Opened event allows template reapply');
  check(await page.locator('#pricingRowsTbody input[type=checkbox][name^="event_row_enabled"]').first().isDisabled(),'Opened event permits changing class availability');
  check(await page.locator('#pricingRowsTbody input[name^="event_row_price"]').first().isDisabled(),'Opened event permits price input');
  console.log('Master scheme selection, CSRF, escaping, read-only draft rates and locked event controls browser checks passed.');
 }finally{await browser.close();}
})().catch(error=>{console.error(error);process.exit(1);});
